package com.chronos.education.grade.model;
import com.chronos.model.pojo.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Getter @Setter @NoArgsConstructor @Table(name="edu_course_grade",uniqueConstraints=@UniqueConstraint(name="uk_edu_course_grade_version",columnNames={"gradebook_id","student_id","version_no"}))
public class CourseGrade extends BaseEntity { @Column(name="gradebook_id",nullable=false,length=64) private String gradebookId; @Column(name="student_id",nullable=false,length=64) private String studentId; @Column(name="total_score",nullable=false,precision=8,scale=2) private BigDecimal totalScore; @Column(name="grade_level",length=16) private String gradeLevel; @Column(name="grade_point",precision=5,scale=2) private BigDecimal gradePoint; @Column(nullable=false) private Boolean passed; @Column(name="version_no",nullable=false) private Integer versionNo; @Column(name="snapshot_hash",nullable=false,length=64) private String snapshotHash; }
